{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Viqualine, a piperidine-containing quinoline, had absolute oral bioavailability 0.73 ± 0.07 in volunteers, supporting high F for a basic fused aromatic piperidine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Cibenzoline, a basic heterocyclic drug, showed absolute bioavailability 83% in healthy volunteers, demonstrating that basic aromatic heterocycles without acidic groups can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Bicifadine, a bridged piperidine with an aryl substituent, had approximately 67% oral bioavailability in humans, supporting high F for piperidine-containing small molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rolipram, a small heterocyclic drug, had absolute bioavailability 73 ± 25% in humans, supporting high F for small lipophilic heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Alvimopan, a piperidine with a carboxylic acid and amide, had low absolute bioavailability ~6%; its acidic/polar groups are absent in the query, so this low-F evidence has limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Fenoldopam, a catechol-containing benzazepine, had poor oral bioavailability due to conjugation; the query lacks catechol, limiting transfer of this low-F result.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, basic, fused quinoxaline-piperidine without carboxylic acid or catechol groups. Most transferable experimental evidence from structurally related piperidine/heteroaromatic drugs shows high oral bioavailability (viqualine 73-80%, cibenzoline 83-92%, bicifadine 67%, rolipram 73%), while low-F analogues contain acidic or catechol moieties absent in the query. Therefore predict high (F ≥ 20%).",
  "evidence_gaps": [
    "Morgan similarities are low (0.16-0.22), so direct structural transfer is limited.",
    "No direct experimental bioavailability record exists for the query molecule.",
    "The mCIPP record is ambiguous, with reported values ranging from about 10% to more than 100%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

